// ORDERED simulation of the three wallet steps (and the rollback pair) on a LOCAL Anvil fork of Base at a pinned block,
// the owner IMPERSONATED (no key exists here; anvil accepts unsigned sends from an impersonated account). Nothing
// reaches the real chain: every send goes to 127.0.0.1. The upgrade and config transactions are generated by the
// EXISTING CLI (--rpc <fork> --unsigned --from <owner>, empty HOME), exactly as root would generate them after each
// step mines; the publish calldata is the one release-prep.mjs simulated on the live chain (same sha256).
//   node fork-sim.mjs <port>
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawn, execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { createRequire } from 'node:module';
const require = createRequire('/home/steven/Documents/Codex/2026-10-18/wo/work/enclave/package.json');
const { createPublicClient, createTestClient, http, encodeFunctionData, keccak256, toHex, formatEther } = require('viem');

const PORT = Number(process.argv[2] || 18545), FORK = `http://127.0.0.1:${PORT}`;
const UPSTREAM = 'https://base.gateway.tenderly.co';
const CLI = '/home/steven/Documents/Codex/2026-10-18/wo/work/enclave/cli/enclave.mjs';
const OWNER = '0x0b2d009c0c9Af05b12100D77F3c815fea822eE61', CATALOG = '0x18419CA2b502D423A8de6269AEeE171a378626e3';
const DEP = '0xd9798e4ccd0c8402d0042000513fc6bc14616043d96dff3368080a21a1abbb9a';
const APP_ID = '0x9afdfb401d6f2cfea70c446f9f5874bbca8ce7dd116e2b15715312d8d32a65ef';
const sha = (b) => createHash('sha256').update(b).digest('hex');
const prep = JSON.parse(fs.readFileSync('release-prep.json', 'utf8'));
const V5CFG = fs.readFileSync('version-config-v5.json', 'utf8'), DESC = fs.readFileSync('app-description.txt', 'utf8');
const ps = prep.publishSimulation.args;
const ABI = [{ type: 'function', name: 'publishVersion', stateMutability: 'nonpayable', inputs: [{ type: 'string' }, { type: 'string' }, { type: 'string' }, { type: 'string' }, { type: 'string' },
  { type: 'uint32[4]' }, { type: 'string' }, { type: 'string' }, { type: 'uint256' }], outputs: [{ type: 'bytes32' }, { type: 'uint256' }] },
  { type: 'function', name: 'getVersionsPage', stateMutability: 'view', inputs: [{ type: 'bytes32' }, { type: 'uint256' }, { type: 'uint256' }], outputs: [{ type: 'tuple[]', components: [
    { name: 'cid', type: 'string' }, { name: 'version', type: 'string' }, { name: 'vramMb', type: 'uint32' }, { name: 'gpuGflops', type: 'uint32' }, { name: 'memMb', type: 'uint32' },
    { name: 'cpuGflops', type: 'uint32' }, { name: 'createdAt', type: 'uint64' }, { name: 'verified', type: 'bool' }, { name: 'yanked', type: 'bool' }, { name: 'ports', type: 'string' },
    { name: 'approval', type: 'uint8' }, { name: 'config', type: 'string' }] }] }];
const publishData = encodeFunctionData({ abi: ABI, functionName: 'publishVersion',
  args: ['ipns-publisher', 'IPNS Publisher', DESC, ps.version, ps.cid, ps.res, ps.ports, V5CFG, BigInt(ps.feePerSec6)] });
const out = { at: new Date().toISOString(), fork: { upstream: UPSTREAM }, steps: [] };
out.publishDataSha256 = sha(Buffer.from(publishData.slice(2), 'hex'));
out.publishDataEqualsLiveSimulated = out.publishDataSha256 === prep.publishSimulation.dataSha256;

const home = fs.mkdtempSync(path.join(os.tmpdir(), 'enclave-empty-home-'));
const ENV = { PATH: process.env.PATH, HOME: home, XDG_CONFIG_HOME: path.join(home, '.config'), NODE_NO_WARNINGS: '1' };
// a cold fork answers slowly (every slot is fetched upstream): a CLI read that times out is retried; anvil keeps what it
// already fetched in memory, so a retry is cheaper. Only timeouts are retried, never a refusal.
function cli(args) {
  let r; for (let i = 0; i < 4; i++) { r = cli1(args); if (!(r.rc && /timed out|took too long|fetch failed/i.test(r.err || ''))) break; r.retries = i + 1; }
  return r;
}
function cli1(args) {
  try { const o = execFileSync('node', [CLI, '--rpc', FORK, '--json', ...args], { env: ENV, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], timeout: 180000 });
    const t = o.trim(); return { rc: 0, j: t.includes('{') ? JSON.parse(t.slice(t.indexOf('{'))) : null, text: t.slice(0, 300) }; }
  catch (e) { return { rc: e.status, err: String(e.stderr || '').trim().split('\n').slice(-2).join(' | ').slice(0, 300) }; }
}
// the block: a FRESH one two RPCs agree on (same hash); a non-archive upstream cannot serve an old block's state
const rp = ['https://mainnet.base.org', UPSTREAM].map((u) => createPublicClient({ transport: http(u, { timeout: 20000, retryCount: 1 }) }));
const hd = await Promise.all(rp.map((c) => c.getBlockNumber())); const FB = (hd[0] < hd[1] ? hd[0] : hd[1]) - 5n;
const fh = await Promise.all(rp.map((c) => c.getBlock({ blockNumber: FB }).then((x) => x.hash)));
if (fh[0] !== fh[1]) { console.log(JSON.stringify({ error: 'RPCs disagree on the fork block', FB: String(FB), fh })); process.exit(2); }
out.fork.block = Number(FB); out.fork.agreedHash = fh[0];
const anvil = spawn('anvil', ['--fork-url', UPSTREAM, '--fork-block-number', String(FB), '--port', String(PORT), '--host', '127.0.0.1',
  '--silent', '--no-storage-caching', '--timeout', '30000', '--retries', '5', '--fork-retry-backoff', '2000', '--compute-units-per-second', '200'], { stdio: ['ignore', 'ignore', 'pipe'] });
let anvilErr = ''; anvil.stderr.on('data', (d) => { anvilErr += d; });
const stop = () => { try { anvil.kill('SIGKILL'); } catch {} fs.rmSync(home, { recursive: true, force: true }); };
process.on('exit', stop);
const pc = createPublicClient({ transport: http(FORK, { timeout: 60000 }) });
const tc = createTestClient({ mode: 'anvil', transport: http(FORK, { timeout: 60000 }) });
let up0 = false, exited = null; anvil.on('exit', (c) => { exited = c; });
for (let i = 0; i < 240 && exited === null; i++) { try { await pc.getChainId(); up0 = true; break; } catch { await new Promise((r) => setTimeout(r, 500)); } }
if (!up0) { console.log(JSON.stringify({ error: 'anvil did not come up', exited, anvilStderr: anvilErr.slice(-800) })); stop(); process.exit(3); }
const forkHash = (await pc.getBlock({ blockNumber: FB })).hash;
out.fork.hash = forkHash; out.fork.hashMatchesAgreed = forkHash === fh[0]; out.fork.chainId = await pc.getChainId();
out.ownerEthAtBlock = formatEther(await pc.getBalance({ address: OWNER, blockNumber: FB }));
await tc.impersonateAccount({ address: OWNER });
// the LIVE Base gas price (upstream eth_gasPrice), not anvil's default: the cost figures are then realistic
const GAS_PRICE = await rp[1].getGasPrice(); out.liveGasPriceWei = String(GAS_PRICE);
out.topUps = [];
async function send(label, tx) {
  const params = [{ from: OWNER, to: tx.to, data: tx.data, value: '0x0', gasPrice: toHex(GAS_PRICE) }];
  let hash;
  try { hash = await pc.request({ method: 'eth_sendTransaction', params }); }
  catch (e) {
    if (!/insufficient funds/i.test(String(e.details || e.message))) throw e;
    // the owner's REAL balance does not cover this step at the live gas price: recorded, then topped up ON THE FORK
    // ONLY so the remaining steps can still be checked
    const bal = await pc.getBalance({ address: OWNER });
    out.topUps.push({ beforeStep: label, ownerEthOnFork: formatEther(bal) });
    await tc.setBalance({ address: OWNER, value: bal + 10n ** 16n });
    hash = await pc.request({ method: 'eth_sendTransaction', params });
  }
  const r = await pc.waitForTransactionReceipt({ hash });
  const step = { step: label, to: tx.to, value: '0', dataSha256: sha(Buffer.from(tx.data.slice(2), 'hex')), status: r.status, gasUsed: String(r.gasUsed),
    costEth: formatEther(r.gasUsed * r.effectiveGasPrice), logs: r.logs.length };
  out.steps.push(step); return { r, step };
}
const versions = async () => pc.readContract({ address: CATALOG, abi: ABI, functionName: 'getVersionsPage', args: [APP_ID, 0n, 50n] });
const envelope = async () => { const s = cli(['--unsigned', '--from', OWNER, 'config', 'show', DEP]); return s.j?.envelope ?? null; };
const env0 = await envelope();
out.before = { envelopeSha256: env0 && sha(env0), envelope: env0, versionCount: (await versions()).length };

// 1. publish 1.0.6 (owner = catalog owner on a rev-9 catalog: approved on publish)
const p = await send('1 publishVersion 1.0.6', { to: CATALOG, data: publishData });
const APPROVAL = keccak256(toHex('VersionApprovalSet(bytes32,uint256,uint8)'));
const v = await versions(); const v6 = v[6];
Object.assign(p.step, { approvalEventInReceipt: p.r.logs.some((l) => l.topics[0] === APPROVAL),
  v6: v6 && { version: v6.version, cid: v6.cid, approval: v6.approval, yanked: v6.yanked, memMb: v6.memMb, cpuGflops: v6.cpuGflops, ports: v6.ports, configSha256: sha(v6.config) } });
// 2. upgrade to 1.0.6, generated by the CLI against the post-publish state
const up = cli(['--yes', '--unsigned', '--from', OWNER, 'upgrade', DEP, '1.0.6']);
if (!up.j?.unsigned) { out.upgradeCli = up; } else {
  const u = await send('2 upgrade -> 1.0.6 (CLI-generated)', up.j.unsigned); u.step.cli = 'upgrade ' + DEP + ' 1.0.6';
  const again = cli(['--yes', '--unsigned', '--from', OWNER, 'upgrade', DEP, '1.0.6']); u.step.cliAfter = again.text || again.err;
}
// 3. config set with the HOLD file, generated by the CLI against the post-upgrade state
const cs = cli(['--yes', '--unsigned', '--from', OWNER, 'config', 'set', DEP, '--file', '../publisher-config-allblocks.HOLD.json']);
if (!cs.j?.unsigned) { out.configCli = cs; } else {
  const c = await send('3 config set HOLD (CLI-generated)', cs.j.unsigned);
  const e = await envelope(); const cfg = JSON.parse(e).config;
  Object.assign(c.step, { envelopeSha256: sha(e), announceAllBlocks: cfg?.ipni?.announceAllBlocks,
    configEqualsHold: JSON.stringify(cfg) === JSON.stringify(JSON.parse(fs.readFileSync('../publisher-config-allblocks.HOLD.json', 'utf8'))) });
}
out.after = { envelopeSha256: sha(await envelope()) };
// rollback pair, generated the same way: back to 1.0.5, then the current config
const rbU = cli(['--yes', '--unsigned', '--from', OWNER, 'upgrade', DEP, '1.0.5']);
if (rbU.j?.unsigned) { const s = await send('R1 rollback upgrade -> 1.0.5 (CLI-generated)', rbU.j.unsigned); const a = cli(['--yes', '--unsigned', '--from', OWNER, 'upgrade', DEP, '1.0.5']); s.step.cliAfter = a.text || a.err; } else out.rollbackUpgradeCli = rbU;
const rbC = cli(['--yes', '--unsigned', '--from', OWNER, 'config', 'set', DEP, '--file', '../publisher-config-current.json']);
if (rbC.j?.unsigned) await send('R2 rollback config set current (CLI-generated)', rbC.j.unsigned); else out.rollbackConfigCli = rbC;
const envR = await envelope();
out.rollback = { envelopeSha256: envR && sha(envR), envelope: envR, equalsBefore: envR === env0 };
out.unsignedTxs = { upgrade: up.j?.unsigned ?? null, configSet: cs.j?.unsigned ?? null, rollbackUpgrade: rbU.j?.unsigned ?? null, rollbackConfigSet: rbC.j?.unsigned ?? null };
out.anvilStderrTail = anvilErr.slice(-300);
console.log(JSON.stringify(out, (k, x) => typeof x === 'bigint' ? x.toString() : x, 1));
stop(); process.exit(0);
